INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Climb 2', 'The thrill of climbing comes alive with The Climb 2 - explore a new city setting and exhilarating new maps with breathtaking views. Ascend grand peaks, navigate vast caves, climb skyscrapers, and discover hidden shortcuts as you find your path to the top. Compete with friends and conquer leaderboards in asynchronous multiplayer modes. From exploring mountain environments to scaling urban settings, feel the rush of climbing without ropes, and experience breathtaking vistas as you scale new heights.' FROM games WHERE igdb_id = 144372 ON CONFLICT (game_id, language_code) DO NOTHING;
