INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tensura: King of Monsters', 'That Time I Got Reincarnated as a Slime: King of Monsters presents you with Ranga, Shuna, Benimaru, Shion, and other Monster Federation members to form a unique powerful monster legion! In the game heroes are divided into output, defensive, and assistant types. Arrange them in a 3x3 grid to bring their attributes and properties into play and display your strategic battle array! Dispatch heroes with close bond to trigger their synergy skills with astonishing destructive force! At critical moments, suppress the enemy with smooth, awesome combo skills!' FROM games WHERE igdb_id = 142849 ON CONFLICT (game_id, language_code) DO NOTHING;
