INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Morto: Chapter 1', 'Morto is a heavy and enigmatic game that focuses on a psychological horror story with a hand-drawn and animated aesthetic. The game is being created in a structure of chapters that will be released over time. In it you control a mysterious character and can walk and interact with objects in a 2D view, finding tense scenes and also trying to find out more about the story by exploring the environments, this game focuses heavily on the theme of depression so it should be avoided by those who have this predisposition.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 163700 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
