INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroland: Knowble Edition', 'The Heroland theme park offers guests an authentic RPG-style adventure for a price, but when a scruffy young park guide and his guests uncover ulterior motives by the organizers, legends become reality, and guests must take the fate of the park (and the world!) into their own hands. Created by an all-star development team consisting of key people behind MOTHER 3, Legend of Mana, and Fantasy Life, this 2D adventure brings not only a host of quirky heroes and their unique abilities to join your party for a new take on classic RPG-style combat but also a colorful cast of monsters employed by the theme park, many with their own stories to tell!' FROM games WHERE igdb_id = 136194 ON CONFLICT (game_id, language_code) DO NOTHING;
