INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apollo LM', '3D fly and land the Apollo Lunar Module on the moon! Easy and precise control with one finger. Real moon topology mapping. Rewrite humanity''s greatest achievement and... Land the 1st woman on the moon! Place your country''s flag on the moon! Apollo mission dialogue voices transcription. Be Miss or Mr Armstrong. Evolve your Astronaut level. Evolve the Lunar Module. Challenge your astronaut friends through the Game Center.' FROM games WHERE igdb_id = 174288 ON CONFLICT (game_id, language_code) DO NOTHING;
