INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digital Terrarium: Pogona Virtual Pet', 'Digital Terrarium - Pogona is a simple virtual pet game. As the title implies, it''s a virtual terrarium set up to care for a pogona lizard, more commonly known as a bearded dragon. The game features some customization options for your terrarium, as well as the color morph of your bearded dragon, which is a simple AI that wanders the tank and drinks periodically, as well as eats the cricket you can drop into the tank. It also includes an infographic with some educational text about bearded dragons.' FROM games WHERE igdb_id = 175846 ON CONFLICT (game_id, language_code) DO NOTHING;
