INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MLB Tap Sports Baseball 2021', 'Your MLB baseball game is BACK with MLB Tap Sports Baseball 2021! Get in the game and continue your MLB dynasty! Throw HEAT for the first time in TSB history with new Pitching Labs, and team up with your Club mates to defeat our new Club Rally event for HUGE rewards! Plus, new World Rankings Seasons means you can assert your dominance and win season rewards each season. MLB Tap Sports Baseball 2021 contains more authentic MLB baseball content than ever before, with new ways to compete in events that mirror the real events of the MLB. Build your team and MLB dynasty in your MLB baseball game: MLB Tap Sports Baseball 2021!' FROM games WHERE igdb_id = 149138 ON CONFLICT (game_id, language_code) DO NOTHING;
