INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('burn-supertrucks', 142836, '2021-01-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co576y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9z9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burn! SuperTrucks', 'The championship regulations in the ¬´ SuperTrucks ¬ª mode require you to get over large metal ramps at different strategic points, where control and anticipation in each jump are essential to ranking among the best drivers. Compete in championship mode on different tracks, located and designed throughout the entire USA. Drive from north to south, from the coast to the highest peaks. Win the gold cup and raise it over your head at each of them. Any experienced driver can mess up and cause an accident. But don''t worry! because you have the option ¬´ flashback ¬ª, which turns back the clock to just before the accident for a new chance, and it''s all done in slow motion (bullet time). With several weather settings, each race will always feel different at all times. In training mode, you can practice on an oval circuit with the vehicles that have already been unlocked. Get the best times in the time trial mode and upload them to the world ranking. The challenge is to be number 1 on the world podium among your colleagues, friends or family. Burn! SuperTrucks offers you a passionate and extreme driving experience, with incredible skids and dizzying jumps, where your adrenaline will be through the roof at all times. But don''t forget! You yourself are your worst rival.' FROM games WHERE igdb_id = 142836 ON CONFLICT (game_id, language_code) DO NOTHING;
