INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Ops Arcade', 'Red Ops Arcade is a survival and fighting game that takes place across different worlds. The player has to fight zombies, monsters, ghosts and many other enemies, using different weapons that he will find in mystery boxes. The player must reach the highest round possible, but be careful because as higher is the level, more difficult will be to finish it.' FROM games WHERE igdb_id = 193516 ON CONFLICT (game_id, language_code) DO NOTHING;
