INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmic Commute', 'Cosmic Commute is a surreal space comedy set in a world stranger than fiction: the public transport system. Playing as everyone''s least favourite discount cop - a ticket inspector - discover that even unfathomable creatures have relatable problems.' FROM games WHERE igdb_id = 229624 ON CONFLICT (game_id, language_code) DO NOTHING;
