INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rhythm Retro', 'With R.P.G. elements, audio calibration settings, an online leaderboard, 7 gold medal achievements, 6 class upgrade ranks, and even keyboard controls for Blue-stack players! This game will work on any mobile device after 2014 with Android OS. You don''t even need a touch screen to play! Challenge yourself with 120 unique gameplay combinations! Level up your Retro Boosts and blow the competition away! Creatively unique, and designed to fulfill your enjoyment! Rhythm Retro is the ultimate Tap Rhythm Music Game!' FROM games WHERE igdb_id = 182178 ON CONFLICT (game_id, language_code) DO NOTHING;
