INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('comix-breaker', 174262, '2021-08-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co86sg.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Comix Breaker', 'Comix Breaker is a deckbuilding roguelike game optimized for the mobile platform. Defeat various monsters from comics with unique style. New comics are continuously updated and monsters evolve to get in your hair. Find your unique card and snack combinations. You will play a time-attack game with 5 opponents within a 20-minute time limit. Win in the Competitive Mode, and gain the honor of the winner as well as huge rewards!' FROM games WHERE igdb_id = 174262 ON CONFLICT (game_id, language_code) DO NOTHING;
