INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Octarina', 'Octarina is a physics-based 3D puzzle platformer featuring a trapped little octopus who must find a way out and escape out of a sushi factory site. You play as an adorable little octopus, which is trapped inside an aquarium for its whole life. Not as a pet, but rather as a sushi ingredient. Escape your captivity and find a way out before it''s too late! Use the sticky abilities of Octarina to jump, climb and cause mayhem in the factory. Discover your way to regain freedom!' FROM games WHERE igdb_id = 150760 ON CONFLICT (game_id, language_code) DO NOTHING;
