INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ant Empire', 'Ant Empire is a tactical strategy and management game set in a world where ant species battle to become the top empire. This deeply detailed and nostalgic turn-based simulation is a mix of many popular older games-- but with a much more modern feel. Select from 5 unique species that feature characteristics in the game based on how the species actually behaves naturally.' FROM games WHERE igdb_id = 109705 ON CONFLICT (game_id, language_code) DO NOTHING;
