INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('number-pinocchio-super-puzzles-dream', 158787, '2021-07-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3g8e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arxnr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '#Pinocchio: Super Puzzles Dream', 'Puzzles move onto the next level with ‘Super Puzzle Dream’, a mix between classic jigsaw and a ‘Tetris’-style dynamic mechanic. #Pinocchio is the hashtag for a classic tale that teaches children what happens when they are disobedient and tell lies. Pinocchio will learn to obey, to be responsible, not to trust strangers and to appreciate school, but most importantly: it teaches us the importance of telling the truth. All this is told accompanied by beautiful drawings.
