INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Encounter the Light', '这是一个关于爱、梦想与信念的故事。 玩家需要扮演的是一位拥有进入病人梦境能力的心理医师，你将通过梦境中的只言片语与异常现象拼凑出埋藏在病人心底的桎梏，从而对症下药。 游戏将重心放在流畅细腻的叙事上，更近似于一部视觉小说。' FROM games WHERE igdb_id = 150802 ON CONFLICT (game_id, language_code) DO NOTHING;
