INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Olympic Table Tennis', 'Challenge many AI levels opponents in this table tennis simulation and win the Olympic Tournament! Olympic Table Tennis is a new way of playing table tennis, totally different from other table tennis games on store: here, the paddle follows the ball, you concentre on where you want to send it and the lift effect to apply. The goal is to leave the computer away from the ball. Full 3D, the game is driven by a highly realistic physics engine. 6 different paddles to choose from each with their own physical characteristics.' FROM games WHERE igdb_id = 142530 ON CONFLICT (game_id, language_code) DO NOTHING;
