INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Meatball', 'Super Meatball is game combine race car ,foot ball and meatball!? You can play with your friend in local multiplayer mode. The rule is easy. Shoot the fork on your car to get the meatball and bring the meatball into the shark''s mouth to get 1 score. The team with higher score after a 3 minutes match is the winner!' FROM games WHERE igdb_id = 147779 ON CONFLICT (game_id, language_code) DO NOTHING;
