INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Too Impatient', 'Too Impatient is a short story with straightforward gameplay about a demon that loves to torture people mentally. The game includes two endings, a highschool boy that doesn''t look both ways before crossing the street and a story that was made up on a whim over the school break.' FROM games WHERE igdb_id = 191470 ON CONFLICT (game_id, language_code) DO NOTHING;
