INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Top Boat: Racing Simulator 3D', 'Top Boat combines extreme mind-blowing visuals and sound with breathtaking gameplay. Experience top-notch graphics with realistic world settings and amazingly detailed ocean-going rides on powerboats and motorboats. Pick and tune to perfection one of the 25+ powerboats from 6 unique boat classes: hovercraft, classic, offshore, catamaran, jetski, and hydroplane. Customize your boat by tuning its appearance and slap on some decals if you want to! Are you fed up with standard boat racing games? Then you should definitely take a look at this one! Top Boat is setting a new standard in the boat racing genre. Jump on a jetski and experience the most amazing water action out there!' FROM games WHERE igdb_id = 172843 ON CONFLICT (game_id, language_code) DO NOTHING;
