INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lines Splitter', 'Lines Splitter is a 2021 line puzzle game where you will have ultimate fun by solving line riddles. Lines Splitter has taken the puzzle standards to a whole new different level where creativity meets the brain power. In this brand new riddle game 2021 you will find one hundred exigent levels, a rich collection of Smileys, soothing sound and challenging puzzles that will cling you to the gameplay.' FROM games WHERE igdb_id = 142876 ON CONFLICT (game_id, language_code) DO NOTHING;
