INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asobu Tights', 'The web animation "Miru Tights" by the popular illustrator "Yomu". The fresh and fetishistic tights anime is now available on Nintendo Switch as a puzzle game! You can meet Ren, Yua, Homi and Yuiko again at! ・It''s a 3-match puzzle game with easy controls. ・There are 15 stage levels, and special effects for clearing all stages! ・You can use the points you accumulate to redeem your collection! ・All you can see is the animation and illustrations, including new illustrations by the original author! ・The game is available in English and Chinese (simplified and traditional) as well as Japanese!' FROM games WHERE igdb_id = 145964 ON CONFLICT (game_id, language_code) DO NOTHING;
