INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape from the Village', 'You are on your way home from a holiday and your car breaks down and you are stranded in the middle of nowhere. You get out of the car, explore the surroundings, and try to get home. Enjoy this escape game set in a deserted mountain village in modern Japan.' FROM games WHERE igdb_id = 180017 ON CONFLICT (game_id, language_code) DO NOTHING;
