INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Go Rally', 'With loads of tracks, cars, a career mode, multiplayer time challenges and an awesome track creator, Go Rally is the only rally game you''ll ever need! Draw a line on your screen, tap the ''race'' icon, and instantly drive your very own track! Add hills, bridges, checkpoints, trackside banners, houses and terrain - create the circuit of your dreams, then share on-line and challenge your friends, and the world, to beat your times.' FROM games WHERE igdb_id = 197691 ON CONFLICT (game_id, language_code) DO NOTHING;
