INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psychofunk', 'You control the platforms, not the hero, in this groovy platformer. Go on a psychedelic adventure inspired by the trippy 60s and funky 70s. Get ready for a platforming challenge unlike anything you''ve ever experienced. Psychofunk is a platforming game were you push the platforms in and out like the buttons on an old cassette player. Travel through the four seasons into madness and fight intense boss fights. This game will challenge you.' FROM games WHERE igdb_id = 161776 ON CONFLICT (game_id, language_code) DO NOTHING;
