INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City Pipes', 'City pipes is the next best brain-teaser for every pipeline puzzle lover. If you are a big fan of pipe connection puzzle, do not miss this next great pipeline puzzle game! Connect the city with water and solve the puzzles! Everyone can enjoy the fun of plumbing and connecting the right pipes in the right orientation! An amusing, inspiring pipe puzzle experience . All pipe plumbing fans, get ready for your exciting pipe plumbing puzzle journey in over 100 levels!' FROM games WHERE igdb_id = 186574 ON CONFLICT (game_id, language_code) DO NOTHING;
