INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shark-copter-vs-zombie-dancers', 147976, '2021-01-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5asa.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ararv.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shark Copter vs. Zombie Dancers', 'One day in August 2030, an outbreak of a zombie virus was confirmed at a festival in Japan! The infection spread in a blink of an eye, and the venue was filled with zombies. If the virus spreads overseas as it is, humankind will be in great danger. In such a case, there is one possibility to deal with an emergency ... A doctor was studying sharks. As a result of many years of research, They succeeded in creating a "remodeled shark / shark copter". A shark copter with strong jaws and sharp fang, and it''s not likely to be infected by remodeling Can it be the hope of humankind? The fate of human survival was entrusted to one shark! Eliminate the outbreak of zombies and rescue the remaining survivors!' FROM games WHERE igdb_id = 147976 ON CONFLICT (game_id, language_code) DO NOTHING;
