INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abyss the Forgotten Past', 'Abyss The Forgotten Past, is a 2D platform game with RPG-based mechanics, with a large diversity of collectible items, increasing the difficulty as you progress. The story is based on rediscovering itself, after an unfortunate event, Leonnor sets out on a journey to discover everything about his past, with special abilities, where monsters, magic and heavenly beings exist. Enter a personal search that will surprise you with each discovery ...' FROM games WHERE igdb_id = 143189 ON CONFLICT (game_id, language_code) DO NOTHING;
