INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('coalhero', 154396, '2021-06-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3nc7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arv1d.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Coalhero', '故事是從這裡開始的—某天主角因公司倒閉而失業，那樣的年代失業可不是小事，要是無法賺錢養家餬口，他們一家三口可不是要露宿街頭？這種時候不論做什麼工作他都願意！此時天外飛來的傳單，像是天降奇蹟般地拯救了他。於是他下定決心，去薪水高但充滿危險與怪物的礦坑工作。礦工作為礦坑中的勇者，雖然有著極高的薪水，但他們要剷除礦坑中的各種怪物，化解所有危機，能夠從危機重重的礦坑中，將煤礦帶回礦坑外的礦工，被人們譽為「黑金勇者」。' FROM games WHERE igdb_id = 154396 ON CONFLICT (game_id, language_code) DO NOTHING;
