INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hella Dazzling Hell!!', '龙皇社东方同人作品第三作LH03-东方十昊狱！ 本游戏是一款2D横板的东方project二次同人动作RPG游戏，拥有宏大的叙事和独具特色的武器合成/组装系统，玩家将扮演救灾小队穿行于幻想乡各处，探索隐藏的秘宝并调查异变的成因。' FROM games WHERE igdb_id = 156856 ON CONFLICT (game_id, language_code) DO NOTHING;
