INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mountain-bike-hill-climb-race-real-2d-arcade-dirt-racing-games', 173137, '2021-09-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5amc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1506.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mountain Bike Hill Climb Race: Real 2D Arcade Dirt Racing Games', 'Mountain Bike Hill Climb Race is an exciting, 2D action Bicycle driving game based on real physics with funny cartoon graphics and parallax scrolling. Drive your mountain bike through paths and hurdles over beautifull hills and amazing mountains. It is a very addictive, simple 2D game, yet challenging to play. Use the left control stick to lean back or forward and the right control stick to speed up and slow down. Make stunts, run through jumps and flips, lean back on a rear wheel drive while browsing the 42 challenging levels available now. Go uphill or downhill on glaciers in the mountains and dangerous slopes with obstacles like tree trunks and rocks. Discover extreme sensations on a half pipe or pyramid in a snow resort to achieve the best time. The more you play, the better you become in handling the bicycle at high speed, but accelerate with caution as you may have a steep fall or sharp rising around the next corner. The challenge lies in landing savely on just two wheels and mastering the handling of your bicycle in order to become a 2D simulator stunts champ. So don''t wait any longer, perform different cycling stunts, tricks and indulge yourself in this cycling excitement to get an adrenaline rush through the huge, beautifull mountains and hills!' FROM games WHERE igdb_id = 173137 ON CONFLICT (game_id, language_code) DO NOTHING;
