INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Francisca 2', 'Francisca 2 – a first-person indie horror game. Every day you’ll have to survive in your own house. At the start of each level, you need to place video cameras inside the house and in the yard and conceal yourself as well as you can, because a ghost girl is going to visit you soon.' FROM games WHERE igdb_id = 156073 ON CONFLICT (game_id, language_code) DO NOTHING;
