INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sluggish Morss: Pattern Circus', 'A claymation 2d adventure game set in a dark and cryptic future. Another Time Expression, a temporal interference phenomenon, has been predicted leaving those that govern anxious. You will discover its effects on the lives of eight playable characters; a hunter, a dreamer, an artist, a child; a racer, a fighter, a scientist and a detective. Explore an intricate, tactile world full of feverish, intertwining stories told with humour, irreverence and melancholy.' FROM games WHERE igdb_id = 139541 ON CONFLICT (game_id, language_code) DO NOTHING;
