INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Choju Yokai Giga', 'The mysterious Yokai Monogatari has been opened, unleashing Yokai into the world! Help Miko seal them away and restore peace to the village. Build your deck and summon animals to defeat Yokai in this side-scrolling platformer! The longer you go without touching the ground, the more cards you will receive when you finally land. Play cards to summon animals with different effects, and collect sake to keep them on the field. Since Miko can''t do any direct damage, be smart about where to place the summoned animals!' FROM games WHERE igdb_id = 151684 ON CONFLICT (game_id, language_code) DO NOTHING;
