INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('three-kingdoms-written-words', 157538, '2021-07-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co44m9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arx16.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Three Kingdoms Written Words', '《文字三国》是一款三国修仙游戏，在这里你将穿越到三国修真世界，招募群雄豪杰，一起踏上仙途，修仙问道，称霸九州。 放置玩法，简单轻松，一键即可领取丰厚收益！ 每个伙伴都有自己的专属定位，变换阵容及站位，跨战力通关不是梦！ 更有形式各异玩法，军团远征，多人BOSS，矿脉争夺，攻城战、以及不重复的迷宫探险，各种玩法嗨翻天！' FROM games WHERE igdb_id = 157538 ON CONFLICT (game_id, language_code) DO NOTHING;
