INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzle Box 3 in 1', 'Puzzle Box 3 in 1 is a small puzzle collection of the top trending puzzle games. In Crazy Numbers you swipe up numbered blocks in a row to merge same numbers up or you add or subtract numbers to match the same numbers in a grid of blocks in merge plus. And in connect the dots you connect the same color with a line without crossing another one. Enjoy!' FROM games WHERE igdb_id = 151600 ON CONFLICT (game_id, language_code) DO NOTHING;
