INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyberfrags ''69', 'Move fast and shoot fast in Cyberfrags ''69. Double jump, wall-run, and blast your way to victory in intense PvP and Co-Op, or play as Cyber-Frank as he slaughters the Cyber-Nazis invading his home! It''s time to get your blood up with some lightning-speed FPS action! Double-jump, wall-run, slide, and shoot your way to victory in PvP, Co-op, and single-player. In CF69, the fastest way to die is to stop moving. So don''t.' FROM games WHERE igdb_id = 185885 ON CONFLICT (game_id, language_code) DO NOTHING;
