INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wowowow Korone Box', 'WOWOWOW KORONE BOX is a fangame based off of Cover Corporation’s hololive property. It features Inugami Korone, member of hololive GAMERS. The game is a top-down shooter with the objective of collecting as many Korone Boxes as possible without getting hit even once. Korone must contend with many enemies and boss battles, but is given a variety of weapons to help her survive. The game is inspired by Vlambeer’s Super Crate Box and Nuclear Throne.' FROM games WHERE igdb_id = 165402 ON CONFLICT (game_id, language_code) DO NOTHING;
