INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('empire-invasion', 147135, '2021-04-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57mn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arb9x.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Empire Invasion', 'Empire Invasion is an engaging and fun tower defense game. The main focus in this title is to try and keep your base safe against a variety of enemies attacking it. You have 40+ levels to test your skills, each one coming with 3 difficulty levels. It helps you test your skills in a rewarding and engaging manner, and you will find the experience to be very exciting and a lot of fun. You have 7 basic pillars, a tower upgrade system and endless replay value and strategies. You can also mix and match to see how fast you eliminate enemies. The power is in your hands, do you have what it takes to defend the kingdom? Features: 40+ levels to play through Engaging, fun tower defense gameplay 3 difficulty levels 7 basic pillar types, each can be upgraded' FROM games WHERE igdb_id = 147135 ON CONFLICT (game_id, language_code) DO NOTHING;
