INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('glams-incredible-run-escape-from-dukha', 146682, '2021-02-18', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co41b4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arwkg.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glam''s Incredible Run: Escape from Dukha', 'Glam has the most unique ability in the video game history She can grab branches and swing by using her hair. Controls are simple: three buttons and a Stick. Master your, swinging and jumping skills on the epic obstacles courses where each death is a lesson. In this game you play as Glam, her goal is to rescue her mother from the realm of Caterina. She is being held captive by the evil witch to prevent Glam’s and her mother’s power to unite. The levels are made with various items and enemies, each level rewards your climbing skills and agility. The levels are packed into 11 chapters, each chapter has its own unique peril: hanging cubes, goblins and skulls, sliding and spinning platforms, false floors, cannons, crates. Teamwork is crucial in local co-op mode, where you will have to work together to reach the portals to unlock the next level. 60 challenging levels are waiting for two of you to explore. Features: Hand crafted obstacle courses to test the limits of your acrobatic skills Tight, precise and simple controls: just three buttons and the Stick 220+ Single player levels, split into 11 chapters each has its own unique peril 60 multiplayer levels that demands endurance, flexibility and excepcional precise coordination of your movement Customizable character hero: Glam Charming music' FROM games WHERE igdb_id = 146682 ON CONFLICT (game_id, language_code) DO NOTHING;
