INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'N.E.O.N.: Never-Ending Onslaught of Nerds', 'We''ve missed going to in-person events this past year and feel the isolation, so we decided to replicate the convention experience! You are a famous cosplayer and influencer, and it''s your job to smile for the camera... with a Never-Ending Onslaught of Nerds! (...Hey, that''s us!) How long can YOU last before things get... Awkward?!' FROM games WHERE igdb_id = 152922 ON CONFLICT (game_id, language_code) DO NOTHING;
