INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blocky Puzzle', 'BLOCKY PUZZLE is a challenging puzzle game where you need to fit all the shapes in the grid to complete the level. Put the shapes to the right place on the game board without empty spaces and every shape in place. Features: - Supports Square, Triangle, and Hexagon shaped levels. - Starts simple and gets progressively more difficult' FROM games WHERE igdb_id = 152429 ON CONFLICT (game_id, language_code) DO NOTHING;
