INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '4x4 Archipelago', 'Adventure waits for you in a procedurally generated Archipelago! Discover strange new lands. Make a fortune from trading. Swing a Really Big Sword at a dragon. Fight wild beasts – or turn them into your allies. Meet the puffins (if you''re really lucky). With dozens of possible enemies, quests, and items, no two visits to the Archipelago are the same.' FROM games WHERE igdb_id = 230566 ON CONFLICT (game_id, language_code) DO NOTHING;
