INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-quintessential-quintuplets-summer-memories-also-come-in-five-limited-edition', 167012, '2021-03-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co87u1.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Quintessential Quintuplets: Summer Memories Also Come in Five - Limited Edition', 'Based on the manga with the same name, it follows a new storyline that sees Futaro trapped with the girls on a tropical island as a brief summer getaway is stretched out over weeks. There, Futaro will interact with the sisters, Ichika, Nino, Miku, Yotsuba, and Itsuki, as well as Futaro''s younger sister, Raiha. Players can unlock new artwork, costumes, and up to 14 endings. The gameplay promises a "heart-pounding desert island life" and a "five-girl tutoring adventure experience."
