INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love Pop!', 'Draw lines on the screen to send love and kisses to your neighbors. Guide the heart through more than 100 levels full of obstacles and evil neighbors who will want to keep your love. And this is not the only thing! On your way you will find other caged hearts waiting to be rescued so you can play with them. Let love be unleashed in the neighborhood!' FROM games WHERE igdb_id = 186954 ON CONFLICT (game_id, language_code) DO NOTHING;
