INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('farmquest', 186552, '2021-11-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57nb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1c3p.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farmquest', 'Everything on Joe''s farm is in chaos. Everything urgently needs to be put back in order here. Help Joe find important objects and hidden treasures on his farm. Who doesn''t love them? The small and detailed hidden object pictures that challenge children to find certain items. They have been proven to promote children''s perception and language progression. Farmquest can be played by children of any age. Thanks to the voice output, even toddlers are able to explore the hidden object pictures on their own. They do not need to be able to read to have a sense of achievement. Concentration and attentiveness are taught in a playful way. Incidentally, a study conducted by the Singapore Technological University proved the fact that hidden object games increase the understanding of spatial perception in memory. In addition, visual search skills were noticeably improved. The game can also be used to support language learning. Simply select the desired language in the settings and start playing. What are you waiting for?' FROM games WHERE igdb_id = 186552 ON CONFLICT (game_id, language_code) DO NOTHING;
