INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monster-rancher-2-dx', 184783, '2021-12-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4a6j.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Rancher 2 DX', 'Welcome to the magical world of Monster Rancher! The beloved series makes its triumphant return with Monster Rancher 1 & 2 DX, bringing together the wildly popular simulation games – Monster Rancher and Monster Rancher 2 – all in one amazing collection. Raise your own monsters and train them to compete against other eccentric creatures in combat and tournaments. With hundreds of different monster types, each with their own skills and abilities, every Rancher will be able to raise and train a monster that''s a perfect fit for their personality and play style. Returning fans and newcomers alike can enjoy the timeless monster training and battling experience in Monster Rancher 1 & 2 DX!' FROM games WHERE igdb_id = 184783 ON CONFLICT (game_id, language_code) DO NOTHING;
