INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MechCube: Dark Stories', 'This is the second point-and-click game from the MechCube series - a truly titanic structure discovered by an ill-fated expedition in the ancient ice of Antarctica. The Cube consists of many rooms; in the center of each room there is a puzzle device; once you solve the puzzle you can unlock the doors to the adjacent rooms. But be careful! The space and time inside the Cube are intermixed; an open door can lead you to prehistoric Earth, to a dimension of unimaginable horror, or into the vacuum of open space!' FROM games WHERE igdb_id = 174283 ON CONFLICT (game_id, language_code) DO NOTHING;
