INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Property Brothers Home Design', 'Drew and Jonathan Scott, famously known as the Property Brothers, need you to help clients achieve their home design dreams! With the brothers at your side, you’ll demo, renovate, customize, and design spaces with the same charm and style the twins have become known for. Play along to go behind the scenes with the brothers, learn their design tips and tricks, and discover fun facts about TV’s favorite design duo. Relaxing, fun puzzles let you earn coins to spend on décor. Exclusive voice-overs from the twins will give you all the encouragement you need to become a design star yourself!' FROM games WHERE igdb_id = 187801 ON CONFLICT (game_id, language_code) DO NOTHING;
