INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Next Step', 'With only one day left before he moves for college, Wallace must make the most of his last day with Deacon at the big graduation party called Next Step. The only problem is he hasn''t told him that he''s leaving just yet. Can Wallace muster up the courage to tell his best friend about the move? And maybe tell him about something else?' FROM games WHERE igdb_id = 178655 ON CONFLICT (game_id, language_code) DO NOTHING;
