INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soma Union', 'Set 100 years after the true ending of Soma Spirits, Soma Union is a galaxy-spanning RPG that returns to the world of Soma! ...or so it would, if Soma had not been destroyed in a great calamity. As you roam through the cosmos to find the missing fragments of your home world, you''ll meet a colorful cast of characters and make important choices that may not be as clear as they seem.' FROM games WHERE igdb_id = 144855 ON CONFLICT (game_id, language_code) DO NOTHING;
