INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MasterChef: Let''s Cook', 'Do you have what it takes to be the number one chef? Show your cooking abilities in MasterChef: Let’s Cook! A unique, fun, and fast-paced cooking competition game awaits you! Get matched with other players around the globe. Choose your ingredients, slice, prepare, plate, and serve delicious dishes with style in fun mini-games! The MasterChef jury will evaluate your dish based on your performance and speed. Complete and unlock new recipes, challenges, mini-games along your cooking journey!' FROM games WHERE igdb_id = 165294 ON CONFLICT (game_id, language_code) DO NOTHING;
