INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cold Shot', 'Play the role of a contract killer that must perform a job during a cold night. The target is Spencer York, an apparently ordinary man living on the outskirts of a rural town. After driving for hours, everything is settled up to end the job fast. You only have to pull the trigger one more time, like the countless times you did before.' FROM games WHERE igdb_id = 264295 ON CONFLICT (game_id, language_code) DO NOTHING;
