INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bullseye', 'The official Bullseye family game based on television''s classic darts quiz game for 1 to 4 players Put your dart throwing skills and trivia knowledge to the test to win points and ultimately the game. Bullseye is party gaming at it''s very best in an easy, out of the box, pick-up-and-play game that keeps everyone at the edge of their seat. Bullseye is a great way to while away the time, giving a brilliant game show experience at home with family and friends of all ages. Jam packed with 5,000 multiple choice trivia questions in ten genre categories, no game will be the same.' FROM games WHERE igdb_id = 152485 ON CONFLICT (game_id, language_code) DO NOTHING;
