INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Livly Island', 'Livly Island was an Internet browser-based game created in 2003 and was rebooted as a mobile game in 2021. In the new Livly Island, players take on the role of a "homunculus" owner and take care of creatures called livlies. The game additionally features dress-up, island decoration, and message boards for players to communicate.' FROM games WHERE igdb_id = 194764 ON CONFLICT (game_id, language_code) DO NOTHING;
