INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('like-veins-beneath-the-town', 229614, '2021-04-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7xot.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckdbg.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Like Veins Beneath the Town', 'People already have a habit of going missing in the night near that Forest, but this case is a bit... different than the others. 21 women missing. The only evidence washed away in the rain. The village is divided between a select few that desperately want your help and a majority that will make sure you stay out of their affairs, even if you have to be the next one to disappear. Was it kidnapping, murder, or something much more dreadful? Who can you trust? Why was the railway project really abandoned? And what are those strange noises coming from the subway grates? This game will ask many more questions than it will answer-but that never stopped you before, did it now?
