INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzled Love', 'Puzzled Love is a a point-and-click-and-drag-and-drop game where you will cover pictures with other pictures to uncover the love story layer by layer. Meet Jonathan and Lily, the two troubled hearts who have just moved into a new apartment to start a life together—a life that is full of new hopes and beginnings. Or is it?' FROM games WHERE igdb_id = 180813 ON CONFLICT (game_id, language_code) DO NOTHING;
