INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shinya-ichizoku-the-battle-for-hokkaidos-delicious-foods', 186908, '2021-12-23', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1c9p.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shinya Ichizoku: The Battle for Hokkaido''s Delicious Foods', 'Hokkaido, Japan''s Kingdom of Gastronomy! In this action game, members of the popular Japanese TV show "Shinya Ichizoku" fight off aliens who have attacked Hokkaido in an attempt to steal it. Play against the aliens who attack 179 cities, towns and villages in Hokkaido. By controlling your character, you can collect Hokkaido''s specialties and delicious ingredients that appear on the screen, and give them to the goal, the bear, for points. As you progress through the game, you will collect various Hokkaido delicacies, which will be added to your "Picture Book". Let''s collect all the delicious foods of Hokkaido!' FROM games WHERE igdb_id = 186908 ON CONFLICT (game_id, language_code) DO NOTHING;
