INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('escape-route', 147871, '2021-02-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57mr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arayh.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape Route', 'Escape Route is an intense and engaging stealth game. Your focus here is to try and reach the destination while trying to avoid detection. It’s not easy to do that, and you must do everything you can in order to maintain your stealth and engage your enemies in combat. There are different weapons you need to deal with, like machine guns, press machines, noise detectors, lasers and so on. You need to use all your skills to figure out exactly how to master every level. You get 25 levels to go through, each one with its own range of unique challenges. Do you have what it takes to become the ultimate stealth attacker?' FROM games WHERE igdb_id = 147871 ON CONFLICT (game_id, language_code) DO NOTHING;
