INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Letter To A Friend', 'Letter To A Friend is a short first-person experience by Christoph Frey about the unspeakable horror that creeps up on you at a nightly train station. Its visual references come from expressionistic silent movies and old analog recordings. The game was made in 48 hours during Asylum Jam 2015 and is a proof of concept regarding the visual aesthetics and atmosphere.' FROM games WHERE igdb_id = 251451 ON CONFLICT (game_id, language_code) DO NOTHING;
