INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death Trials', 'Before you know it, you''ve woken up in a SURVIVAL HORROR GAME. Total darkness. It feels like you''re in a rusty metal cage, which hangs in mid air. There''s a small light against the wall twenty feet away, but you can''t get out. Just as your eyes adjust, the cage door slowly opens... You jump from the cage... three feet below to the floor... and into the darkness...' FROM games WHERE igdb_id = 171224 ON CONFLICT (game_id, language_code) DO NOTHING;
