INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pocket-races', 153834, '2021-06-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ap8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru30.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Races', 'Pocket Races allows you to create a minicar race and test your racing skills at your own pace. This is a game where you can easily use your design skills to fully push your racing approach to the next level in a powerful and engaging manner. We are here to offer you access to some of the nicest and most immersive game worlds where you can create cool and fun races. Since Pocket Races has multiple environments to choose from like the kitchen, board games, sand pit or bathroom, you can easily use your imagination and create cool races. Then you can start and test your racing skills against your own time or other players. Check it out today if you want a unique way to create your own races and have fun testing them!' FROM games WHERE igdb_id = 153834 ON CONFLICT (game_id, language_code) DO NOTHING;
