INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Sweeper', 'Tomb Sweeper is an intense and exciting maze game. It''s a unique and interesting title where your focus is to try to move the player from wall to all or corner to corner in order to create a path and complete the level. Once the level is full of color, you can reach the next level.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 163696 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
