INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('drift-racing-madness', 147747, '2021-02-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57f1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbu5.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drift Racing Madness', 'Are you looking for a great game to show off your unbeatable driving talent? You are in the right place. In this game, you can stump yourself and your friends in challenging tracks with magnificent landscapes. Each track comes with different challenges and each car has its own awesome features; Power, Control, Speed. Choose your car! Win the races! And collect the rewards to unlock gorgeous tracks and many different well-designed peerless cars. Now, this is your time to show others how omnipotent you are. An endless competition awaits you, Driver.' FROM games WHERE igdb_id = 147747 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 147747 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;